import { Formik, Form, Field, ErrorMessage } from "formik";

import "./Registration.css";

const Registration = () => {
  const initialValues = {
    image: "",
    fisrt: "",
    last: "",
    maid: "",
    age: "",
    gender: "",
    email: "",
    phone: "",
    bisthdate: "",
  };



  return (
    <div>
      <Formik initialValues={initialValues}>
        <Form>
          <Field name="image" placeholder="Image url"></Field>
          <Field name="fisrt" placeholder="Firstname"></Field>
          <Field name="last" placeholder="Lastname"></Field>
          <Field name="maid" placeholder="Maidenname"></Field>
          <Field name="age" placeholder="Age"></Field>
          <Field name="gender" placeholder="Gender"></Field>
          <Field name="email" placeholder="Email" type="email"></Field>
          <Field name="phone" placeholder="Phone number"></Field>
          <Field
            name="birthdate"
            placeholder="Birthdate (ex. 2000-1-1)"
          ></Field>
        </Form>
      </Formik>
    </div>
  );
};

export default Registration;
